'use strict';

const SCORE_TABLE = [50,45,42,40,39,38,37,36,35,34,33,32,31,30,29,28];
const EVENT_POINTS = [25,18,15,12,10,8,6,4,2,1];
const FINAL_A_RUNS = ['A1','A2','A3'];

function uid(prefix='id'){return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function deepClone(v){return JSON.parse(JSON.stringify(v));}

function makeRace(input={}){
  const now=new Date().toISOString();
  return {
    id:uid('race'),eventName:input.eventName||'Новая гонка',clubName:input.clubName||'Legion RC',eventDate:input.eventDate||new Date().toISOString().slice(0,10),eventLocation:input.eventLocation||'',eventStatus:input.eventStatus||'club',championshipId:input.championshipId||'',championshipStageNumber:input.championshipStageNumber||null,qualifyingCount:Number(input.qualifyingCount||4),publishAllowed:false,
    pilots:[],heats:[],finals:[],finalProtocol:[],exactTieLots:{},stage:'setup',lifecycleStatus:'active',createdAt:now,updatedAt:now,completedAt:'',
    raceSettings:{qualificationMinutes:Number(input.qualificationMinutes||5),finalLaps:Number(input.finalLaps||7),countdownSec:Number(input.countdownSec||5),minLapSec:Number(input.minLapSec||2)},
    runtime:{activeEventKey:'',session:null,eventResults:{},eventLog:[]}
  };
}

function makePilot(profile={},registrationOrder=1){
  return {id:profile.id||uid('pilot'),profileId:profile.profileId||profile.id||'',name:profile.name||'Пилот',club:profile.club||'',city:profile.city||'',photo:profile.photo||'',transponder:String(profile.transponder||''),registrationOrder,qualifying:[],best3:0,points:0,best3Rounds:[],finalResults:[]};
}
function getPilot(race,id){return race.pilots.find(p=>String(p.id)===String(id));}

function getPoints(place){if(!Number.isInteger(place)||place<1)return 0;return SCORE_TABLE[place-1]??Math.max(1,29-place);}
function qualifyingResultRank(result){if(!result)return 10000;if(result.status==='FIN')return result.place;if(result.status==='DNF')return 100+(result.dnfOrder||99);if(result.status==='DNS')return 300;if(result.status==='DSQ')return 400;return 500;}
function savePilotResult(pilot,round,heat,resultValue,dnfOrder=null){
  const existing=pilot.qualifying.find(r=>r.round===round);const isPlace=Number.isInteger(resultValue);const record={round,heat,place:isPlace?resultValue:null,status:isPlace?'FIN':resultValue,dnfOrder:resultValue==='DNF'&&Number.isInteger(dnfOrder)?dnfOrder:null,points:isPlace?getPoints(resultValue):0};
  if(existing)Object.assign(existing,record);else pilot.qualifying.push(record);
}
function getBest3Results(pilot){return [...pilot.qualifying].sort((a,b)=>{if(b.points!==a.points)return b.points-a.points;const rd=qualifyingResultRank(a)-qualifyingResultRank(b);if(rd!==0)return rd;return b.round-a.round;}).slice(0,3);}
function getDiscardedResults(pilot){const sel=new Set(getBest3Results(pilot).map(i=>`${i.round}:${i.heat}`));return pilot.qualifying.filter(i=>!sel.has(`${i.round}:${i.heat}`)).sort((a,b)=>{if(b.points!==a.points)return b.points-a.points;const rd=qualifyingResultRank(a)-qualifyingResultRank(b);if(rd!==0)return rd;return b.round-a.round;});}
function calculateBest3(pilot){const best=getBest3Results(pilot);pilot.best3=best.reduce((s,r)=>s+r.points,0);pilot.points=pilot.best3;pilot.best3Rounds=best.map(r=>r.round);}
function placeHistogram(results,maxPlace=16){const h=[];for(let p=1;p<=maxPlace;p++)h.push(results.filter(r=>r.status==='FIN'&&r.place===p).length);return h;}
function compareNumberArraysDesc(a,b){const len=Math.max(a.length,b.length);for(let i=0;i<len;i++){const av=a[i]??-Infinity,bv=b[i]??-Infinity;if(bv!==av)return bv-av;}return 0;}
function compareResultArraysByQuality(a,b){const len=Math.max(a.length,b.length);for(let i=0;i<len;i++){const ar=a[i],br=b[i];if(!ar&&!br)continue;if(!ar)return 1;if(!br)return -1;if(br.points!==ar.points)return br.points-ar.points;const rd=qualifyingResultRank(ar)-qualifyingResultRank(br);if(rd!==0)return rd;}return 0;}
function comparePilotsWithoutLot(race,a,b){if(b.best3!==a.best3)return b.best3-a.best3;const bestA=getBest3Results(a),bestB=getBest3Results(b);const hd=compareNumberArraysDesc(placeHistogram(bestA),placeHistogram(bestB));if(hd!==0)return hd;const dd=compareResultArraysByQuality(getDiscardedResults(a),getDiscardedResults(b));if(dd!==0)return dd;for(let round=race.qualifyingCount;round>=1;round--){const rd=qualifyingResultRank(a.qualifying.find(r=>r.round===round))-qualifyingResultRank(b.qualifying.find(r=>r.round===round));if(rd!==0)return rd;}return 0;}
function comparePilots(race,a,b){const s=comparePilotsWithoutLot(race,a,b);if(s!==0)return s;const la=race.exactTieLots?.[String(a.id)],lb=race.exactTieLots?.[String(b.id)];if(Number.isInteger(la)&&Number.isInteger(lb)&&la!==lb)return la-lb;return (a.registrationOrder||9999)-(b.registrationOrder||9999);}
function updateStandings(race){race.pilots.forEach(calculateBest3);race.pilots.sort((a,b)=>comparePilots(race,a,b));return race.pilots;}
function getExactTieGroups(race){updateStandings(race);const groups=[];for(let i=0;i<race.pilots.length;){let g=[race.pilots[i]],j=i+1;while(j<race.pilots.length&&comparePilotsWithoutLot(race,race.pilots[i],race.pilots[j])===0){g.push(race.pilots[j]);j++;}if(g.length>1)groups.push(g);i=j;}return groups;}
function runTieDraw(race){race.exactTieLots=race.exactTieLots||{};getExactTieGroups(race).forEach(group=>{const arr=[...group];for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}arr.forEach((p,i)=>race.exactTieLots[String(p.id)]=i+1);});updateStandings(race);}

function getHeatCount(pilotCount){if(pilotCount<=6)return 1;return Math.ceil(pilotCount/6);}
function buildSnakeHeats(pilots,heatCount,round){const shift=pilots.length?(round-1)%pilots.length:0;const ordered=[...pilots.slice(shift),...pilots.slice(0,shift)];const heats=Array.from({length:heatCount},()=>[]);ordered.forEach((pilot,index)=>{const row=Math.floor(index/heatCount),column=index%heatCount,heatIndex=row%2===0?column:heatCount-1-column;heats[heatIndex].push(pilot);});return heats.filter(h=>h.length);}
function createQualifyingData(race){race.heats=[];const pilots=[...race.pilots].sort((a,b)=>(a.registrationOrder||0)-(b.registrationOrder||0));const heatCount=getHeatCount(pilots.length);for(let round=1;round<=race.qualifyingCount;round++){buildSnakeHeats(pilots,heatCount,round).forEach((hp,idx)=>race.heats.push({key:`Q${round}-H${idx+1}`,type:'qualifying',label:`Квалификация ${round} · Заезд ${idx+1}`,round,heat:idx+1,pilots:hp.map(p=>p.id),saved:false,result:[],enabled:round===1&&idx===0,order:round*100+idx}));}}
function prepareRace(race){race.finals=[];race.finalProtocol=[];race.exactTieLots={};race.stage='qualifying';race.pilots.forEach(p=>{p.qualifying=[];p.best3=0;p.points=0;p.finalResults=[];});createQualifyingData(race);normalizeQualifyingEnabled(race);return race;}
function normalizeQualifyingEnabled(race){const unsaved=race.heats.filter(h=>!h.saved).sort((a,b)=>a.order-b.order);race.heats.forEach(h=>h.enabled=false);if(unsaved[0])unsaved[0].enabled=true;}
function saveQualifyingEvent(race,eventKey,result){const heat=race.heats.find(h=>h.key===eventKey);if(!heat||heat.saved)throw new Error('Заезд не найден или уже сохранён');heat.result=normalizeResult(result);heat.saved=true;heat.result.forEach((item,index)=>{const p=getPilot(race,item.pilotId);if(!p)return;if(item.status==='FIN')savePilotResult(p,heat.round,heat.heat,item.place??index+1);else savePilotResult(p,heat.round,heat.heat,item.status,item.dnfOrder);});updateStandings(race);normalizeQualifyingEnabled(race);if(race.heats.every(h=>h.saved)){const ties=getExactTieGroups(race).filter(g=>g.some(p=>!Number.isInteger(race.exactTieLots?.[String(p.id)])));if(ties.length)race.stage='tie';else generateFinals(race);}return heat;}
function resolveQualificationTie(race){runTieDraw(race);generateFinals(race);return race.finals;}

function createFinal(name,pilots=[],options={}){return {key:`F-${name}`,name,label:options.label||name,type:options.type||'lcq',round:Number(options.round||0),order:Number(options.order||0),pilots:pilots.map(p=>p?.id||p),basePilots:pilots.map(p=>p?.id||p),result:[],saved:false,enabled:Boolean(options.enabled),advanceCount:Number(options.advanceCount||0)};}
function finalByName(race,name){return race.finals.find(f=>f.name===name);}
function qualificationRankMap(race){const m=new Map();race.pilots.forEach((p,i)=>m.set(String(p.id),i+1));return m;}
function splitSnake(pilots,groupCount){const groups=Array.from({length:groupCount},()=>[]);if(groupCount<=1)return[pilots.slice()];let index=0,direction=1;pilots.forEach(p=>{groups[index].push(p);if(direction>0){if(index===groupCount-1){direction=-1;index-=1;}else index+=1;}else{if(index===0){direction=1;index+=1;}else index-=1;}});return groups;}
function addFinalARuns(race,pilots,enabledFirst=false,startOrder=1000){FINAL_A_RUNS.forEach((name,index)=>race.finals.push(createFinal(name,pilots,{type:'main',label:`Финал ${name}`,order:startOrder+index,enabled:enabledFirst&&index===0})));}
function createPreliminaryRound(race,pilotIdsOrObjects,round,startOrder){const groupCount=Math.ceil(pilotIdsOrObjects.length/6),groups=splitSnake(pilotIdsOrObjects,groupCount);groups.forEach((group,index)=>race.finals.push(createFinal(`P${round}-${index+1}`,group,{type:'prelim',label:`Предварительный LCQ ${round}.${index+1}`,round,order:startOrder+index,enabled:true,advanceCount:1})));}
function generateFinals(race){updateStandings(race);race.finals=[];race.finalProtocol=[];race.pilots.forEach(p=>p.finalResults=[]);const pilots=[...race.pilots],count=pilots.length;if(count<=6)addFinalARuns(race,pilots,true);else{const remaining=pilots.slice(4);if(count<=10)race.finals.push(createFinal('LCQ',remaining,{type:'single-lcq',label:'Заезд последнего шанса (LCQ)',order:100,enabled:true,advanceCount:2}));else if(count<=16){const groups=splitSnake(remaining,2);race.finals.push(createFinal('LCQ-B',groups[0],{type:'dual-lcq',label:'LCQ B',round:1,order:100,enabled:true,advanceCount:1}));race.finals.push(createFinal('LCQ-C',groups[1],{type:'dual-lcq',label:'LCQ C',round:1,order:101,enabled:true,advanceCount:1}));}else createPreliminaryRound(race,remaining,1,100);addFinalARuns(race,[],false);}race.stage='finals';return race.finals;}
function compareFinalResultItems(a,b){const r={FIN:0,DNF:1,DNS:2,DSQ:3};if(r[a.status]!==r[b.status])return r[a.status]-r[b.status];if(a.status==='FIN')return(a.place||999)-(b.place||999);if(a.status==='DNF')return(a.dnfOrder||999)-(b.dnfOrder||999);return 0;}
function classifiedForAdvancement(result){return result.filter(i=>i.status==='FIN'||i.status==='DNF');}
function setMainGrid(race,lastTwo){const qTop4=race.pilots.slice(0,4).map(p=>p.id),grid=[...qTop4,...lastTwo].slice(0,6);FINAL_A_RUNS.forEach((name,index)=>{const f=finalByName(race,name);if(f){f.pilots=[...grid];f.basePilots=[...grid];f.enabled=index===0;}});}
function processPreliminaryRound(race,round){const finals=race.finals.filter(f=>f.type==='prelim'&&f.round===round);if(!finals.length||!finals.every(f=>f.saved))return;const winners=finals.map(f=>classifiedForAdvancement(f.result)[0]?.pilotId).filter(Boolean);if(winners.length<=6){if(!finalByName(race,`LCQ-F${round}`))race.finals.push(createFinal(`LCQ-F${round}`,winners,{type:'final-lcq',label:'Заключительный LCQ',round:round+1,order:500+round,enabled:true,advanceCount:2}));}else{const next=round+1;if(!race.finals.some(f=>f.type==='prelim'&&f.round===next))createPreliminaryRound(race,winners,next,100+next*50);}}
function advanceFinalists(race,final){if(final.type==='single-lcq'){setMainGrid(race,classifiedForAdvancement(final.result).slice(0,2).map(i=>i.pilotId));return;}if(final.type==='dual-lcq'){const pair=race.finals.filter(f=>f.type==='dual-lcq');if(pair.every(f=>f.saved)){const rank=qualificationRankMap(race),w=pair.map(f=>classifiedForAdvancement(f.result)[0]?.pilotId).filter(Boolean).sort((a,b)=>(rank.get(String(a))||9999)-(rank.get(String(b))||9999));setMainGrid(race,w);}return;}if(final.type==='prelim'){processPreliminaryRound(race,final.round);return;}if(final.type==='final-lcq'){setMainGrid(race,classifiedForAdvancement(final.result).slice(0,2).map(i=>i.pilotId));return;}if(final.type==='main'){const idx=FINAL_A_RUNS.indexOf(final.name);if(idx<2){const n=finalByName(race,FINAL_A_RUNS[idx+1]);if(n)n.enabled=true;}else buildFinalProtocol(race);}}
function saveFinalEvent(race,eventKey,result){const final=race.finals.find(f=>f.key===eventKey);if(!final||!final.enabled||final.saved)throw new Error('Финал закрыт или уже сохранён');final.result=normalizeResult(result).sort(compareFinalResultItems);final.saved=true;final.result.forEach((item,index)=>{const p=getPilot(race,item.pilotId);if(p)p.finalResults.push({final:final.name,place:item.place,status:item.status,dnfOrder:item.dnfOrder,order:index+1});});advanceFinalists(race,final);return final;}
function mainRunScore(item){return item?.status==='FIN'?Number(item.place||7):7;}
function buildMainStandings(race){const rank=qualificationRankMap(race),main=FINAL_A_RUNS.map(n=>finalByName(race,n)).filter(Boolean),pilotIds=main[0]?.pilots||[];return pilotIds.map(pilotId=>{const results=main.map(f=>f.saved?(f.result.find(i=>String(i.pilotId)===String(pilotId))||{status:'DNS'}):null),scores=results.map(i=>i?mainRunScore(i):null),done=scores.filter(Number.isFinite),bestTwo=[...done].sort((a,b)=>a-b).slice(0,2),latest=[...scores].reverse().find(Number.isFinite);return{pilotId,results,scores,bestTwo,total:bestTwo.length?bestTwo.reduce((s,v)=>s+v,0):null,wins:results.filter(i=>i?.status==='FIN'&&i.place===1).length,seconds:results.filter(i=>i?.status==='FIN'&&i.place===2).length,lastScore:latest??9999,qRank:rank.get(String(pilotId))||9999};}).sort((a,b)=>{if(a.total===null&&b.total!==null)return 1;if(a.total!==null&&b.total===null)return-1;if(a.total!==b.total)return(a.total??9999)-(b.total??9999);return b.wins-a.wins||b.seconds-a.seconds||a.lastScore-b.lastScore||a.qRank-b.qRank;});}
function buildFinalProtocol(race){const main=buildMainStandings(race),added=new Set(main.map(i=>String(i.pilotId))),eliminated=[],rank=qualificationRankMap(race),groups=new Map();race.finals.filter(f=>f.saved&&f.type!=='main').forEach(f=>{const k=f.type==='dual-lcq'?'dual-lcq':f.type==='prelim'?`prelim-${f.round}`:`${f.type}-${f.order}`;if(!groups.has(k))groups.set(k,{order:f.order,finals:[]});groups.get(k).order=Math.max(groups.get(k).order,f.order);groups.get(k).finals.push(f);});[...groups.values()].sort((a,b)=>b.order-a.order).forEach(g=>{const c=[];g.finals.forEach(f=>[...f.result].sort(compareFinalResultItems).forEach((i,index)=>c.push({...i,resultOrder:index+1,source:f.label})));c.sort((a,b)=>a.resultOrder-b.resultOrder||(rank.get(String(a.pilotId))||9999)-(rank.get(String(b.pilotId))||9999));c.forEach(i=>{if(!added.has(String(i.pilotId))){eliminated.push({pilotId:i.pilotId,status:i.status,source:i.source});added.add(String(i.pilotId));}});});race.pilots.forEach(p=>{if(!added.has(String(p.id)))eliminated.push({pilotId:p.id,status:'NC',source:'Квалификация'});});const rows=[...main.map(i=>({pilotId:i.pilotId,status:'FIN',source:`Финал A · ${i.total} очк.`})),...eliminated];race.finalProtocol=rows.map((i,index)=>({place:index+1,pilotId:i.pilotId,status:i.status,source:i.source,eventPoints:['DNS','DSQ'].includes(i.status)?0:(EVENT_POINTS[index]||0)}));race.stage='finished';race.lifecycleStatus='completed';race.completedAt=new Date().toISOString();return race.finalProtocol;}

function normalizeResult(items){
  const arr=(items||[]).map(i=>({pilotId:i.pilotId,status:i.status||'FIN',place:i.status==='FIN'||!i.status?Number(i.place)||null:null,dnfOrder:i.status==='DNF'?Number(i.dnfOrder)||null:null}));
  const fins=arr.filter(i=>i.status==='FIN').sort((a,b)=>(a.place||999)-(b.place||999));fins.forEach((i,idx)=>i.place=idx+1);
  const dnfs=arr.filter(i=>i.status==='DNF');dnfs.forEach((i,idx)=>i.dnfOrder=i.dnfOrder||idx+1);
  return arr.sort(compareFinalResultItems);
}

function eventList(race){
  const q=race.heats.map(h=>({...h,phase:'qualifying'}));const f=race.finals.map(x=>({...x,phase:'finals'}));return [...q,...f].sort((a,b)=>{if(a.phase!==b.phase)return a.phase==='qualifying'?-1:1;return(a.order||0)-(b.order||0);});
}
function currentEvent(race){const all=eventList(race);return all.find(e=>!e.saved&&e.enabled)||all.find(e=>!e.saved&&e.phase==='qualifying')||null;}
function eventStatus(race,event){if(event.saved)return'completed';const cur=currentEvent(race);if(cur&&cur.key===event.key)return'current';if(event.enabled)return'ready';return'locked';}
function eventRule(race,event){if(!event)return null;if(event.type==='qualifying')return{mode:'qualification',limitType:'time',durationMin:race.raceSettings.qualificationMinutes,targetLaps:0,minLapSec:race.raceSettings.minLapSec,finishCurrentLap:true};return{mode:'race',limitType:'laps',durationMin:0,targetLaps:race.raceSettings.finalLaps,minLapSec:race.raceSettings.minLapSec,finishCurrentLap:true};}
function getEventPilots(race,event){return(event?.pilots||[]).map(id=>getPilot(race,id)).filter(Boolean);}

'use strict';

const UUID={SERVICE:'0000fff0-0000-1000-8000-00805f9b34fb',COMMAND:'0000fff3-0000-1000-8000-00805f9b34fb',NOTIFY:'0000fff4-0000-1000-8000-00805f9b34fb'};
const STOP='0F03040005FFFF';
const hexToBytes=hex=>Uint8Array.from((hex.match(/.{1,2}/g)||[]).map(x=>parseInt(x,16)));
const bytesToHex=bytes=>Array.from(bytes).map(b=>b.toString(16).padStart(2,'0').toUpperCase()).join('');
function buildProtocolPacket(command,payload=[]){const out=[0x0F,payload.length+3,command,0,...payload];const checksum=(command+payload.reduce((a,b)=>a+b,0)+1)&0xFF;out.push(checksum,0xFF,0xFF);return Uint8Array.from(out);}
function buildStartWork(settings){const type=settings.mode==='practice'?3:settings.mode==='qualification'?1:2,rule=settings.limitType==='laps'?1:0;let total;if(type===3)total=57600;else if(rule===1)total=Math.max(1,Math.min(65535,Math.round(settings.targetLaps)));else total=Math.max(1,Math.min(65535,Math.round(settings.durationMin*60)));const u16=n=>[(n>>8)&255,n&255];const minLap=Math.max(1,Math.min(65535,Math.round(Number(settings.minLapSec)||1)));return buildProtocolPacket(0x03,[type,rule,...u16(total),...u16(60),...u16(5),...u16(minLap)]);}

class LapWizCore extends EventTarget{
  constructor(){super();this.device=null;this.server=null;this.cmdChar=null;this.notifyChar=null;this.connected=false;this.running=false;this.rxBuffer=[];this.pending={start:null,stop:null};this.sound=true;this.audioCtx=null;}
  emit(type,detail={}){this.dispatchEvent(new CustomEvent(type,{detail}));}
  async connect(){if(!navigator.bluetooth)throw new Error('Web Bluetooth недоступен. Нужен Chrome/Android и HTTPS.');const device=await navigator.bluetooth.requestDevice({filters:[{namePrefix:'LapWiz'}],optionalServices:[UUID.SERVICE]});device.addEventListener('gattserverdisconnected',()=>this.onDisconnected());const server=await device.gatt.connect(),service=await server.getPrimaryService(UUID.SERVICE),cmd=await service.getCharacteristic(UUID.COMMAND),notify=await service.getCharacteristic(UUID.NOTIFY);await notify.startNotifications();notify.addEventListener('characteristicvaluechanged',e=>this.onNotify(e));this.device=device;this.server=server;this.cmdChar=cmd;this.notifyChar=notify;this.connected=true;this.rxBuffer=[];this.emit('status',{connected:true,name:device.name||'LapWiz'});return device.name||'LapWiz';}
  async disconnect(){try{if(this.running)await this.stop();}catch{}if(this.device?.gatt?.connected)this.device.gatt.disconnect();this.onDisconnected();}
  onDisconnected(){const was=this.connected;this.connected=false;this.running=false;this.cmdChar=null;this.notifyChar=null;this.server=null;if(was)this.emit('status',{connected:false,error:'Bluetooth-соединение разорвано'});}
  ack(type,timeout=1800){if(this.pending[type])this.pending[type].reject(new Error('Предыдущая команда отменена'));let timer;return new Promise((resolve,reject)=>{timer=setTimeout(()=>{this.pending[type]=null;reject(new Error(`Нет подтверждения ${type.toUpperCase()}`));},timeout);this.pending[type]={resolve:v=>{clearTimeout(timer);this.pending[type]=null;resolve(v);},reject:e=>{clearTimeout(timer);this.pending[type]=null;reject(e);}};});}
  async write(packet,label='HEX'){if(!this.cmdChar)throw new Error('LapWiz не подключён');const bytes=typeof packet==='string'?hexToBytes(packet):packet;if(this.cmdChar.writeValueWithoutResponse)await this.cmdChar.writeValueWithoutResponse(bytes);else await this.cmdChar.writeValue(bytes);this.emit('log',{kind:'tx',label,raw:bytesToHex(bytes)});}
  async start(settings){const ack=this.ack('start');await this.write(buildStartWork(settings),'START');await ack;this.running=true;this.emit('status',{connected:true,running:true,name:this.device?.name||'LapWiz'});}
  async stop(){if(!this.connected||!this.cmdChar){this.running=false;return;}const ack=this.ack('stop');await this.write(STOP,'STOP');try{await ack;}finally{this.running=false;this.emit('status',{connected:true,running:false,name:this.device?.name||'LapWiz'});}}
  onNotify(event){const view=event.target.value,bytes=new Uint8Array(view.buffer,view.byteOffset,view.byteLength);this.rxBuffer.push(...bytes);this.extractFrames();}
  extractFrames(){while(this.rxBuffer.length){const start=this.rxBuffer.indexOf(0x0F);if(start<0){this.rxBuffer=[];return;}if(start>0)this.rxBuffer.splice(0,start);if(this.rxBuffer.length<2)return;const total=this.rxBuffer[1]+4;if(total<7||total>260){this.rxBuffer.shift();continue;}if(this.rxBuffer.length<total)return;this.handleFrame(new Uint8Array(this.rxBuffer.splice(0,total)));}}
  handleFrame(frame){const cmd=frame[2],raw=bytesToHex(frame);if(cmd===0x03&&frame[1]===0x04){const result=frame[4]??0;if(this.pending.start){result===0?this.pending.start.resolve(frame):this.pending.start.reject(new Error(`START result=${result}`));}return;}if(cmd===0x04&&frame[1]===0x04){const result=frame[4]??0;if(this.pending.stop){result===0?this.pending.stop.resolve(frame):this.pending.stop.reject(new Error(`STOP result=${result}`));}return;}if(cmd===0x02&&frame.length>=13){const id=((frame[4]<<8)|frame[5])>>>0,ticks=((((frame[6]<<24)>>>0)+(frame[7]<<16)+(frame[8]<<8)+frame[9])>>>0);this.emit('pass',{transponder:String(id),deviceTicks:ticks,deviceMs:ticks*10,raw,source:'LAPWIZ'});return;}this.emit('log',{kind:'rx',raw});}
  ensureAudio(){try{this.audioCtx??=new (window.AudioContext||window.webkitAudioContext)();if(this.audioCtx.state==='suspended')this.audioCtx.resume();return this.audioCtx;}catch{return null;}}
  beep(ok=true){if(!this.sound)return;const ctx=this.ensureAudio();if(!ctx)return;const tone=(freq,dur,vol,delay=0)=>{const t=ctx.currentTime+delay,o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+dur+.02);};if(ok)tone(1250,.065,.18);else{tone(430,.09,.15);tone(330,.11,.13,.11);}}
  unknownBeep(){this.beep(false);}
}

'use strict';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEYS={race:'legionrx4_current_race',pilots:'legionrx4_pilot_db',champ:'legionrx4_championships',archive:'legionrx4_archive',settings:'legionrx4_settings'};
const defaultUi={cardRadius:14,tileRadius:14,buttonRadius:9,inputRadius:8,iconRadius:10,heroRadius:18,widgetRadius:12,modalRadius:14,cardPadding:18,sectionGap:14,buttonHeight:48,contentWidth:1240,disciplineCols:3};
const defaultSettings={theme:'light',lang:'ru',lapSound:true,minLapSec:2,qualificationMinutes:5,finalLaps:7,countdownSec:5,ui:{...defaultUi}};
const I18N={
 ru:{'nav.home':'Главная','nav.champs':'Чемпионаты','nav.pilots':'Пилоты','nav.settings':'Настройки'},
 en:{'nav.home':'Home','nav.champs':'Championships','nav.pilots':'Drivers','nav.settings':'Settings'}
};
const storedSettings=load(KEYS.settings,{});
const state={view:'home',race:load(KEYS.race,null),pilotDb:load(KEYS.pilots,[]),championships:load(KEYS.champ,[]),archive:load(KEYS.archive,[]),settings:{...defaultSettings,...storedSettings,ui:{...defaultUi,...(storedSettings.ui||{})}},session:null,sessionTick:null,countdownTick:null,resultsOpen:false,mobileEvents:false,mobileWidgets:false};
const lapwiz=new LapWizCore();
lapwiz.sound=state.settings.lapSound;

function load(key,fallback){try{const v=JSON.parse(localStorage.getItem(key)||'null');return v??fallback;}catch{return fallback;}}
function save(key,v){localStorage.setItem(key,JSON.stringify(v));}
function persistRace(){if(state.race){state.race.updatedAt=new Date().toISOString();save(KEYS.race,state.race);}updateHeader();}
function persistAll(){save(KEYS.pilots,state.pilotDb);save(KEYS.champ,state.championships);save(KEYS.archive,state.archive);save(KEYS.settings,state.settings);persistRace();}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200);}
function fmtMs(ms){if(!Number.isFinite(ms))return'—';const s=Math.max(0,ms)/1000,m=Math.floor(s/60),sec=Math.floor(s%60),cs=Math.floor((s-Math.floor(s))*100);return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(cs).padStart(2,'0')}`;}
function fmtClock(ms){if(!Number.isFinite(ms))return'00:00';const t=Math.ceil(Math.max(0,ms)/1000),m=Math.floor(t/60),s=t%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function nameInitials(name=''){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'RX';}
function uiIcon(name,cls='uiIcon'){
 const paths={
  flag:'<path d="M5 21V5m0 0c5-3 8 3 14 0v9c-6 3-9-3-14 0"/>',
  timer:'<circle cx="12" cy="13" r="8"/><path d="M9 2h6M12 13l3-3M12 5v2"/>',
  car:'<path d="M3 15l2-6h14l2 6v4h-2m-14 0H3v-4h18v4h-2M7 19h10"/><circle cx="7" cy="16" r="1.5"/><circle cx="17" cy="16" r="1.5"/>',
  trophy:'<path d="M8 4h8v4a4 4 0 0 1-8 0V4Z"/><path d="M8 6H4v1a4 4 0 0 0 4 4m8-5h4v1a4 4 0 0 1-4 4M12 12v5m-4 3h8"/>',
  users:'<circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M3 20c0-4 3-7 6-7s6 3 6 7m1-5c3 0 5 2 5 5"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1-2-4-2 1a7 7 0 0 0-2-1l-.3-2h-5l-.3 2a7 7 0 0 0-2 1l-2-1-2 4 2 1a7 7 0 0 0 0 2l-2 1 2 4 2-1a7 7 0 0 0 2 1l.3 2h5l.3-2a7 7 0 0 0 2-1l2 1 2-4-2-1c.1-.3.1-.7.1-1Z"/>',
  bluetooth:'<path d="M7 7l10 10-5 4V3l5 4L7 17"/>',
  chart:'<path d="M4 20V10m6 10V4m6 16v-7m4 7H2"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4m8-4v4M3 10h18"/>',
  mic:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3m-4 0h8"/>',
  monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',
  home:'<path d="M3 11l9-8 9 8v10h-6v-6H9v6H3Z"/>',
  play:'<path d="M8 5v14l11-7Z"/>',
  chevron:'<path d="M9 18l6-6-6-6"/>'
 };
 return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.flag}</svg>`;
}
function translateStatic(){
 const d=I18N[state.settings.lang]||I18N.ru;$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(d[k])el.textContent=d[k];});
 if(state.settings.lang!=='en')return;
 const map={
  'Нет активной гонки':'No active race','Главная':'Home','Чемпионаты':'Championships','Пилоты':'Drivers','Настройки':'Settings','Текущая гонка →':'Current race →','Ралли-кросс':'RallyCross','Создать соревнование':'Create event','Открыть RallyCross':'Open RallyCross','Ралли-спринт':'Rally Sprint','Классическая RC-гонка':'Classic RC race','В разработке':'In development','Открыть':'Open','Общая база':'Driver database','Новый профиль':'New profile','Сохранить':'Save','Название':'Name','Дата':'Date','Место':'Location','Чемпионат':'Championship','Клубная гонка':'Club race','Создать событие':'Create event','Участники':'Participants','Из базы':'From database','＋ Новый':'＋ New','Формат RallyCross':'RallyCross format','Квалификационных серий':'Qualifying rounds','Квалификация, минут':'Qualifying, minutes','Финал, кругов':'Final, laps','Минимальный круг LapWiz, сек':'LapWiz minimum lap, sec','Сформировать заезды и открыть пульт':'Build heats and open control','Удалить событие':'Delete event','Открыть пульт':'Open control','СОБЫТИЯ':'EVENTS','Ход соревнования':'Event flow','ТЕКУЩИЙ ЗАЕЗД':'CURRENT HEAT','Результаты заезда':'Heat results','Таблицы':'Tables','Текущий результат':'Current result','РЕЗУЛЬТАТЫ':'RESULTS','СТАРТ':'START','ФИНИШ':'FINISH','СТОП':'STOP','ПАУЗА':'PAUSE','Подключить':'Connect','Отключить':'Disconnect','Подключить LapWiz':'Connect LapWiz','Отключить LapWiz':'Disconnect LapWiz','Интерфейс':'Interface','Тёмная тема':'Dark theme','Язык интерфейса':'Interface language','Звук прохода':'Pass sound','Значения по умолчанию':'Defaults','О приложении':'About','Сезоны':'Seasons','Мои чемпионаты':'My championships','Новый чемпионат':'New championship','План этапов':'Planned rounds','Создать':'Create','Нет завершённых этапов.':'No completed rounds.','Результаты':'Results','Завершённые заезды':'Completed heats','Итоговый протокол':'Final classification','Квалификационный рейтинг':'Qualifying ranking','Сохранить и перейти дальше':'Save and go to next heat'
 };
 const root=document.getElementById('viewHost');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{const raw=n.nodeValue,trim=raw.trim();if(map[trim])n.nodeValue=raw.replace(trim,map[trim]);});
}
function applyUiTokens(ui=state.settings.ui){const r=document.documentElement.style;r.setProperty('--radius-card',`${ui.cardRadius}px`);r.setProperty('--radius-tile',`${ui.tileRadius}px`);r.setProperty('--radius-button',`${ui.buttonRadius}px`);r.setProperty('--radius-input',`${ui.inputRadius}px`);r.setProperty('--radius-icon',`${ui.iconRadius}px`);r.setProperty('--radius-hero',`${ui.heroRadius}px`);r.setProperty('--radius-widget',`${ui.widgetRadius}px`);r.setProperty('--radius-modal',`${ui.modalRadius}px`);r.setProperty('--card-padding',`${ui.cardPadding}px`);r.setProperty('--section-gap',`${ui.sectionGap}px`);r.setProperty('--control-height',`${ui.buttonHeight}px`);r.setProperty('--content-width',`${ui.contentWidth}px`);r.setProperty('--discipline-cols',String(ui.disciplineCols));}
function applySettings(){document.documentElement.dataset.theme=state.settings.theme;document.documentElement.lang=state.settings.lang;lapwiz.sound=state.settings.lapSound;applyUiTokens();translateStatic();}
function updateHeader(){const race=state.race;$('#headerRace').textContent=race?`${race.eventName} · ${stageLabel(race.stage)}`:'Нет активной гонки';const el=$('#headerLapwiz');el.textContent=lapwiz.connected?`LapWiz · ${lapwiz.device?.name||'подключён'}`:'LapWiz · не подключён';el.className=`statusPill ${lapwiz.connected?'good':'neutral'}`;}
function stageLabel(stage){return({setup:'Настройка',qualifying:'Квалификация',tie:'Жеребьёвка',finals:'Финалы',finished:'Завершено'})[stage]||stage;}

function nav(view){state.view=view;document.body.classList.toggle('cockpitMode',view==='cockpit');$$('#bottomNav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();}
$('#brandBtn').addEventListener('click',()=>nav('home'));$('#settingsBtn').addEventListener('click',()=>nav('settings'));$$('#bottomNav button').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.view)));

function render(){clearIntervalsIfNotCockpit();const host=$('#viewHost');if(state.view==='home')host.innerHTML=homeView();else if(state.view==='rallySetup')host.innerHTML=rallySetupView();else if(state.view==='cockpit')host.innerHTML=cockpitView();else if(state.view==='championships')host.innerHTML=championshipsView();else if(state.view==='pilots')host.innerHTML=pilotsView();else if(state.view==='settings')host.innerHTML=settingsView();bindView();updateHeader();applySettings();}
function clearIntervalsIfNotCockpit(){if(state.view!=='cockpit'){if(state.sessionTick){clearInterval(state.sessionTick);state.sessionTick=null;}if(state.countdownTick){clearInterval(state.countdownTick);state.countdownTick=null;}}}

function homeView(){
 const race=state.race;
 return `<section class="page homePage">
 <div class="heroPanel">
   <div class="heroCopy"><div class="sectionLabel">RACE MANAGEMENT SYSTEM</div><h1>LEGION <span>RX</span></h1><p>Единая система проведения RC-соревнований: пилоты, заезды, результаты и LapWiz — в одном интерфейсе.</p></div>
   <div class="heroStatus">${race?`<div class="liveCard"><span class="liveDot"></span><div><small>АКТИВНОЕ СОБЫТИЕ</small><b>${esc(race.eventName)}</b><span>${stageLabel(race.stage)}</span></div><button class="btn primary" data-action="open-current">Продолжить ${uiIcon('chevron','btnIcon')}</button></div>`:`<div class="heroMini"><b>4.0.4 ALPHA</b><span>Новая оболочка · RallyCross активен</span></div>`}</div>
 </div>
 <div class="homeSectionHead"><div><div class="sectionLabel">ДИСЦИПЛИНЫ</div><h2>Выберите формат соревнования</h2></div></div>
 <div class="disciplineGrid">
  <article class="disciplineTile activeDiscipline"><div class="tileTop"><div class="tileIcon">${uiIcon('flag')}</div><span class="badge liveBadge"><span class="liveDot"></span>АКТИВНО</span></div><div><h3>Ралли-кросс</h3><p>Квалификации, очки, LCQ, переходы и финалы. Рабочий спортивный модуль.</p></div><button class="tileAction" data-action="open-rx"><span>${race?'Открыть соревнование':'Создать соревнование'}</span>${uiIcon('chevron')}</button></article>
  <article class="disciplineTile locked"><div class="tileTop"><div class="tileIcon">${uiIcon('timer')}</div><span class="badge soon">СКОРО</span></div><div><h3>Ралли-спринт</h3><p>Одиночные попытки, лучшее время и протокол результатов.</p></div><button class="tileAction" disabled><span>В разработке</span>${uiIcon('chevron')}</button></article>
  <article class="disciplineTile locked"><div class="tileTop"><div class="tileIcon">${uiIcon('car')}</div><span class="badge soon">СКОРО</span></div><div><h3>Классическая RC-гонка</h3><p>Practice, seeding, qualifying и A/B/C Finals по классической RC-логике.</p></div><button class="tileAction" disabled><span>В разработке</span>${uiIcon('chevron')}</button></article>
 </div>
 <div class="homeSectionHead modulesHead"><div><div class="sectionLabel">СИСТЕМА</div><h2>Общие разделы</h2></div></div>
 <div class="moduleGrid">
  <button class="moduleCard" data-nav="championships"><span class="moduleIcon">${uiIcon('trophy')}</span><span><small>СЕЗОНЫ И ЭТАПЫ</small><b>Чемпионаты</b><em>Турнирные таблицы и очки этапов</em></span>${uiIcon('chevron','moduleArrow')}</button>
  <button class="moduleCard" data-nav="pilots"><span class="moduleIcon">${uiIcon('users')}</span><span><small>ОБЩАЯ БАЗА</small><b>Пилоты</b><em>${state.pilotDb.length} профилей · транспондеры</em></span>${uiIcon('chevron','moduleArrow')}</button>
  <button class="moduleCard" data-nav="settings"><span class="moduleIcon">${uiIcon('settings')}</span><span><small>СИСТЕМА</small><b>Настройки</b><em>Тема, язык, LapWiz, о приложении</em></span>${uiIcon('chevron','moduleArrow')}</button>
 </div>
 </section>`;
}

function rallySetupView(){
 const race=state.race;const step=race?.stage||'setup';return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">RALLYCROSS</div><h1>${race?esc(race.eventName):'Новое соревнование'}</h1><p>Настройка события. После запуска вся работа переходит в одноэкранный пульт.</p></div>${race&&race.stage!=='setup'?`<button class="btn primary" data-action="cockpit">Открыть пульт</button>`:''}</div>
 <div class="setupShell"><aside class="card setupSide"><div class="step ${!race||step==='setup'?'active':'done'}">1 · Событие</div><div class="step ${race&&step==='setup'?'active':race?'done':''}">2 · Пилоты</div><div class="step ${race&&step==='setup'?'active':race?'done':''}">3 · Формат</div><div class="step ${race&&step!=='setup'?'active':''}">4 · Пульт гонки</div></aside>
 <div class="grid">
  <article class="card"><div class="sectionLabel">СОБЫТИЕ</div><h2>Основные данные</h2><div class="formGrid">
   <div class="field"><label>Название</label><input id="raceName" value="${esc(race?.eventName||'Legion RX Cup')}" ${race&&race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Дата</label><input id="raceDate" type="date" value="${esc(race?.eventDate||new Date().toISOString().slice(0,10))}" ${race&&race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Место</label><input id="raceLocation" value="${esc(race?.eventLocation||'')}" placeholder="Трасса / город" ${race&&race.stage!=='setup'?'disabled':''}></div>
   <div class="field"><label>Чемпионат</label><select id="raceChamp" ${race&&race.stage!=='setup'?'disabled':''}><option value="">Клубная гонка</option>${state.championships.map(c=>`<option value="${c.id}" ${race?.championshipId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.season)}</option>`).join('')}</select></div>
  </div>${!race?`<div class="btnRow" style="margin-top:14px"><button class="btn primary" data-action="create-race">Создать событие</button></div>`:''}</article>
  ${race?pilotSetupCard(race):''}
  ${race?formatSetupCard(race):''}
 </div></div></section>`;
}
function pilotSetupCard(race){return `<article class="card"><div class="pageHeader" style="margin:0 0 12px"><div><div class="sectionLabel">ПИЛОТЫ</div><h2>Участники · ${race.pilots.length}</h2></div>${race.stage==='setup'?`<div class="btnRow"><button class="btn secondary" data-action="add-db-pilot">Из базы</button><button class="btn primary" data-action="quick-pilot">＋ Новый</button></div>`:''}</div><div class="list">${race.pilots.length?race.pilots.map((p,i)=>`<div class="listRow"><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${i+1}. ${esc(p.name)}</div><div class="sub">${esc(p.club||'Без клуба')} · транспондер ${esc(p.transponder||'не назначен')}</div></div>${race.stage==='setup'?`<button class="btn secondary" data-remove-race-pilot="${p.id}">Убрать</button>`:''}</div>`).join(''):`<div class="empty">Добавьте минимум двух пилотов.</div>`}</div></article>`;}
function formatSetupCard(race){return `<article class="card"><div class="sectionLabel">ФОРМАТ</div><h2>Параметры RallyCross</h2><div class="formGrid"><div class="field"><label>Квалификационных серий</label><select id="qCount" ${race.stage!=='setup'?'disabled':''}>${[3,4,5].map(n=>`<option ${race.qualifyingCount===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Квалификация, минут</label><input id="qMinutes" type="number" min="1" max="30" value="${race.raceSettings?.qualificationMinutes||state.settings.qualificationMinutes}" ${race.stage!=='setup'?'disabled':''}></div><div class="field"><label>Финал, кругов</label><input id="finalLaps" type="number" min="1" max="99" value="${race.raceSettings?.finalLaps||state.settings.finalLaps}" ${race.stage!=='setup'?'disabled':''}></div><div class="field"><label>Минимальный круг LapWiz, сек</label><input id="minLap" type="number" min="1" max="60" value="${race.raceSettings?.minLapSec||state.settings.minLapSec}" ${race.stage!=='setup'?'disabled':''}></div></div>${race.stage==='setup'?`<div class="btnRow" style="margin-top:14px"><button class="btn primary" data-action="prepare-race" ${race.pilots.length<2?'disabled':''}>Сформировать заезды и открыть пульт</button><button class="btn danger" data-action="delete-race">Удалить событие</button></div>`:`<p>Формат зафиксирован. Изменение структуры после старта отключено, чтобы не разрушить результаты.</p>`}</article>`;}

function cockpitView(){
 if(!state.race||state.race.stage==='setup')return `<section class="page"><div class="card"><h2>Соревнование ещё не подготовлено</h2><button class="btn primary" data-action="open-rx">К настройке</button></div></section>`;
 const race=state.race,ev=currentEvent(race),events=eventList(race),session=ensureSession(ev),pilots=ev?liveRanking(getEventPilots(race,ev),session):[];const done=race.stage==='finished',tie=race.stage==='tie';
 return `<section class="cockpit">
 <aside class="eventRail ${state.mobileEvents?'open':''}" id="eventRail"><div class="eventRailHead"><div><div class="sectionLabel">СОБЫТИЯ</div><b>Ход соревнования</b></div><button class="iconBtn mobileTools" data-action="close-events">×</button></div><div class="eventRailList">${events.map((e,i)=>eventItem(race,e,i)).join('')}${tie?`<div class="eventItem current"><div class="top"><b>🎲 Жеребьёвка</b><span class="eventDot"></span></div><small>Абсолютное равенство после квалификации</small></div>`:''}${done?`<div class="eventItem completed"><div class="top"><b>🏆 Итоговый протокол</b><span class="eventDot"></span></div><small>Соревнование завершено</small></div>`:''}</div></aside>
 <div class="cockpitMain">
  <div class="raceState"><div><div class="mobileTools"><button class="btn secondary" data-action="toggle-events">События</button><button class="btn secondary" data-action="toggle-widgets">Виджеты</button></div><div class="stateTitle"><span class="badge">${done?'ФИНИШ':tie?'ЖЕРЕБЬЁВКА':session?.phase==='running'?'LIVE':session?.phase==='countdown'?'ОТСЧЁТ':'ГОТОВНОСТЬ'}</span><h2>${done?'Соревнование завершено':tie?'Нужно разрешить абсолютное равенство':esc(ev?.label||'Нет активного заезда')}</h2></div><div class="stateMeta">${done?'Откройте итоговую таблицу справа.':tie?'Сохраняем спортивную логику v3.4: перед финалами требуется жеребьёвка равных пилотов.':eventRuleText(race,ev)}</div></div><div><div class="timerCaption">${timerCaption(session,ev)}</div><div id="mainTimer" class="bigTimer">${done||tie?'00:00':displayTimer(session,ev)}</div></div></div>
  <div class="pilotBoard"><div class="pilotBoardHead"><div><div class="sectionLabel">ТЕКУЩИЙ ЗАЕЗД</div><h3>${done?'Итог соревнования':tie?'Квалификационный рейтинг':`${pilots.length} пилотов`}</h3></div><div class="btnRow"><button class="btn secondary" data-action="race-results">Таблицы</button><button class="btn secondary" data-action="toggle-results">${state.resultsOpen?'Скрыть текущий':'Текущий результат'}</button></div></div>
   <div class="pilotBoardTable">${done?finalProtocolTable(race):tie?qualifyingStandingsTable(race):pilotTable(pilots,session)}</div>
  </div>
 </div>
 <aside class="widgetStack ${state.mobileWidgets?'open':''}" id="widgetStack"><div class="mobileTools" style="justify-content:flex-end"><button class="btn secondary" data-action="close-widgets">Закрыть</button></div>
  ${tie?tieWidget(race):resultsWidget(race,ev,pilots,session)}
  ${lapwizWidget()}
  <div class="widget disabled"><div class="widgetHead"><h3>${uiIcon('calendar','widgetIcon')} Расписание / автоматизация</h3><span class="badge soon">СКОРО</span></div><div class="widgetContent">Запуск по времени, предупреждения 10/3/1 мин, сдвиг расписания.</div></div>
  <div class="widget disabled"><div class="widgetHead"><h3>${uiIcon('mic','widgetIcon')} Диктор</h3><span class="badge soon">СКОРО</span></div><div class="widgetContent">Отсчёт, позиции, финиш и переход к следующему заезду.</div></div>
  <div class="widget disabled"><div class="widgetHead"><h3>${uiIcon('monitor','widgetIcon')} Broadcast / OBS</h3><span class="badge soon">СКОРО</span></div><div class="widgetContent">Телевизионная графика и прямая трансляция.</div></div>
 </aside>
 <div class="controlBar">${controlButtons(done,session,tie)}</div>
 </section>`;
}
function eventItem(race,e,i){const s=eventStatus(race,e),pilots=(e.pilots||[]).length;return `<div class="eventItem ${s}" ${s==='completed'?`data-show-event="${e.key}" style="cursor:pointer"`:''}><div class="top"><b>${i+1}. ${esc(e.label)}</b><span class="eventDot"></span></div><small>${pilots} пилотов · ${s==='completed'?'завершён · нажмите для результата':s==='current'?'текущий':s==='ready'?'готов':'закрыт'}</small></div>`;}
function eventRuleText(race,ev){if(!ev)return'Нет активного события';const r=eventRule(race,ev);return r.limitType==='time'?`По времени · ${r.durationMin} мин · финиш текущего круга`:`По кругам · ${r.targetLaps} кругов`;}
function timerCaption(s,ev){if(!ev)return'ГОТОВО';if(s?.phase==='countdown')return'ДО СТАРТА';if(s?.phase==='running')return eventRule(state.race,ev).limitType==='time'?'ДО ФИНИША':'ВРЕМЯ ЗАЕЗДА';if(s?.phase==='finished')return'ЗАЕЗД ОСТАНОВЛЕН';return'ГОТОВНОСТЬ';}
function displayTimer(s,ev){if(!ev)return'00:00';if(!s)return'00:00';if(s.phase==='countdown')return `00:${String(Math.max(0,s.countdownLeft||0)).padStart(2,'0')}`;const r=eventRule(state.race,ev),elapsed=sessionElapsed(s);if(r.limitType==='time')return fmtClock(r.durationMin*60000-elapsed);return fmtClock(elapsed);}
function pilotTable(pilots,session){return `<div class="pilotRow header"><span>POS</span><span>Пилот</span><span>Круги</span><span>Лучший</span><span>Последний</span><span>Отставание</span><span>Ручн.</span></div>${pilots.map((p,i)=>{const l=session?.live?.[p.id]||blankLive();const gap=gapText(pilots,session,p,i);return `<div class="pilotRow ${i===0&&l.laps>0?'leader':''} ${l.finished?'finished':''}" data-pilot-row="${p.id}"><div class="pos">${i+1}</div><div><div class="name">${esc(p.name)}</div><div class="sub">ID ${esc(p.transponder||'—')} ${l.finished?'· Финиш':''}</div></div><b>${l.laps}</b><span>${fmtMs(l.bestLapMs)}</span><span>${fmtMs(l.lastLapMs)}</span><span>${gap}</span><button class="lapButton" data-manual-pass="${p.id}" ${session?.phase!=='running'&&session?.phase!=='finishing'?'disabled':''}>＋1</button></div>`;}).join('')}`;}
function blankLive(){return{laps:0,bestLapMs:Infinity,lastLapMs:null,lastPassPerf:null,lastDeviceTicks:null,elapsedMs:0,finished:false,finishedAt:null,status:'READY'};}
function liveRanking(pilots,session){if(!session)return pilots;return [...pilots].sort((a,b)=>{const A=session.live?.[a.id]||blankLive(),B=session.live?.[b.id]||blankLive();if(B.laps!==A.laps)return B.laps-A.laps;if(A.finished!==B.finished)return A.finished?-1:1;return (A.elapsedMs||Infinity)-(B.elapsedMs||Infinity)||(a.registrationOrder||999)-(b.registrationOrder||999);});}
function gapText(ranked,session,p,index){if(!session||index===0)return index===0?'Лидер':'—';const leader=session.live?.[ranked[0].id]||blankLive(),r=session.live?.[p.id]||blankLive();if(leader.laps-r.laps>0)return `+${leader.laps-r.laps} кр.`;if(r.elapsedMs&&leader.elapsedMs)return `+${fmtMs(Math.max(0,r.elapsedMs-leader.elapsedMs))}`;return'—';}
function resultsWidget(race,ev,pilots,session){if(race.stage==='finished')return `<div class="widget resultsWidget"><div class="widgetHead"><h3>${uiIcon('trophy','widgetIcon')} Итог</h3><span class="badge">ГОТОВО</span></div><div class="widgetContent">${compactFinalProtocol(race)}</div></div>`;if(!ev)return'';const draft=makeDraftResult(pilots,session);return `<div class="widget resultsWidget"><div class="widgetHead"><h3>${uiIcon('chart','widgetIcon')} Результаты заезда</h3><button class="btn secondary" data-action="toggle-results">${state.resultsOpen?'Свернуть':'Развернуть'}</button></div><div class="widgetContent drawerResults ${state.resultsOpen?'open':''}" id="resultDrawer">${draft.map((x,i)=>`<div class="resultEditRow"><div><b>${i+1}. ${esc(x.name)}</b><div class="sub">${x.laps} кр. · ${fmtMs(x.elapsedMs)}</div></div><select data-result-status="${x.pilotId}"><option value="FIN" ${x.status==='FIN'?'selected':''}>FIN</option><option value="DNF">DNF</option><option value="DNS">DNS</option><option value="DSQ">DSQ</option></select><input type="number" min="1" value="${i+1}" data-result-place="${x.pilotId}"></div>`).join('')}<div class="btnRow" style="margin-top:10px"><button class="btn good" data-action="save-event-result" ${session?.phase!=='finished'?'disabled':''}>Сохранить и перейти дальше</button></div></div>${!state.resultsOpen?`<div class="widgetContent">Таблица раскрывается после заезда. Сейчас: ${draft.slice(0,3).map((x,i)=>`${i+1}. ${esc(x.name)}`).join(' · ')||'нет данных'}</div>`:''}</div>`;}
function lapwizWidget(){return `<div class="widget"><div class="widgetHead"><h3>${uiIcon('bluetooth','widgetIcon')} LapWiz Core</h3><span class="badge ${lapwiz.connected?'':'soon'}">${lapwiz.connected?'ПОДКЛЮЧЁН':'OFFLINE'}</span></div><div class="widgetContent"><div>Устройство: <strong>${esc(lapwiz.device?.name||'—')}</strong></div><div>Режим: <strong>${lapwiz.running?'RUNNING':'STOPPED'}</strong></div><div>Звук прохода: <strong>${state.settings.lapSound?'ВКЛ':'ВЫКЛ'}</strong></div><div class="btnRow" style="margin-top:10px">${lapwiz.connected?`<button class="btn secondary" data-action="lap-disconnect">Отключить</button>`:`<button class="btn primary" data-action="lap-connect">Подключить</button>`}</div></div></div>`;}
function controlButtons(done,s,tie=false){if(tie)return `<button class="btn secondary" data-action="toggle-results">Таблица</button><button class="btn secondary" disabled>ПАУЗА</button><button class="btn secondary" disabled>+1 МИН</button><button class="btn primary" data-action="tie-draw">🎲 ЖЕРЕБЬЁВКА</button><button class="btn secondary" disabled>РЕЗУЛЬТАТЫ</button><button class="btn danger" data-action="home">ВЫХОД</button>`;if(done)return `<button class="btn secondary" data-action="home">Главная</button><button class="btn secondary" data-action="open-rx">Настройка</button><button class="btn primary" data-action="race-results">Итоговая таблица</button><button class="btn secondary" disabled>Диктор</button><button class="btn secondary" disabled>Broadcast</button><button class="btn danger" data-action="archive-race">В архив</button>`;const p=s?.phase||'ready';return `<button class="btn secondary" disabled>ПАУЗА</button><button class="btn finishBtn" data-action="finish-session" ${!['running','finishing'].includes(p)?'disabled':''}>ФИНИШ</button><button class="btn secondary" disabled>+1 МИН</button><button class="btn startBtn" data-action="start-session" ${!['ready','finished'].includes(p)||p==='finished'?'disabled':''}>СТАРТ</button><button class="btn secondary" data-action="race-results">РЕЗУЛЬТАТЫ</button><button class="btn danger" data-action="stop-session" ${!['running','finishing','countdown'].includes(p)?'disabled':''}>СТОП</button>`;}

function qualifyingStandingsTable(race){updateStandings(race);return `<div class="pilotRow header"><span>POS</span><span>Пилот</span><span>Best 3</span><span>Q</span><span></span><span></span><span></span></div>${race.pilots.map((p,i)=>`<div class="pilotRow"><div class="pos">${i+1}</div><div class="name">${esc(p.name)}</div><b>${p.best3}</b><span style="grid-column:4/7">${(p.qualifying||[]).map(q=>q.status==='FIN'?`${q.place} (${q.points})`:q.status).join(' · ')}</span><span></span></div>`).join('')}`;}
function tieWidget(race){const groups=getExactTieGroups(race);return `<div class="widget resultsWidget"><div class="widgetHead"><h3>Жеребьёвка · абсолютное равенство</h3><span class="badge soon">ТРЕБУЕТ ДЕЙСТВИЯ</span></div><div class="widgetContent">${groups.map(g=>`<div style="padding:6px 0"><b>${g.map(p=>esc(p.name)).join(' · ')}</b></div>`).join('')}<button class="btn primary" data-action="tie-draw">Провести жеребьёвку и сформировать финалы</button></div></div>`;}

function finalProtocolTable(race){if(!race.finalProtocol?.length)return'<div class="empty">Финальный протокол ещё не сформирован.</div>';return `<div class="pilotRow header"><span>POS</span><span>Пилот</span><span>Очки</span><span>Источник</span><span></span><span></span><span></span></div>${race.finalProtocol.map(r=>{const p=getPilot(race,r.pilotId);return `<div class="pilotRow"><div class="pos">${r.place}</div><div class="name">${esc(p?.name||'—')}</div><b>${r.eventPoints}</b><span style="grid-column:4/7">${esc(r.source)} ${r.status!=='FIN'?`· ${r.status}`:''}</span><span></span></div>`;}).join('')}`;}
function compactFinalProtocol(race){return race.finalProtocol.slice(0,10).map(r=>`<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--line)"><span>${r.place}. ${esc(getPilot(race,r.pilotId)?.name||'—')}</span><b>${r.eventPoints}</b></div>`).join('');}

function ensureSession(ev){if(!ev)return null;if(state.session?.eventKey!==ev.key){state.session={eventKey:ev.key,phase:'ready',startedAtPerf:null,startedAtEpoch:null,finishedAtEpoch:null,countdownLeft:state.race.raceSettings.countdownSec,live:Object.fromEntries(getEventPilots(state.race,ev).map(p=>[p.id,blankLive()])),unknown:{},lastPass:''};}return state.session;}
function sessionElapsed(s){if(!s?.startedAtPerf)return 0;if(s.finishedAtEpoch&&s.startedAtEpoch)return s.finishedAtEpoch-s.startedAtEpoch;return performance.now()-s.startedAtPerf;}
function startTicker(){if(state.sessionTick)clearInterval(state.sessionTick);state.sessionTick=setInterval(()=>{if(state.view!=='cockpit')return;updateDynamicCockpit();checkSessionLimit();},120);}
function updateDynamicCockpit(){const timer=$('#mainTimer');if(timer){const ev=currentEvent(state.race);timer.textContent=displayTimer(state.session,ev);}const board=$('.pilotBoardTable');const ev=currentEvent(state.race);if(board&&ev&&state.session&&state.session.phase!=='finished'){const ranked=liveRanking(getEventPilots(state.race,ev),state.session);board.innerHTML=pilotTable(ranked,state.session);bindManualPasses();}}
async function beginCountdown(){const ev=currentEvent(state.race),s=ensureSession(ev);if(!ev||s.phase!=='ready')return;s.phase='countdown';s.countdownLeft=state.race.raceSettings.countdownSec;render();state.countdownTick=setInterval(async()=>{s.countdownLeft--;if(s.countdownLeft<=0){clearInterval(state.countdownTick);state.countdownTick=null;await beginRaceNow();}else updateDynamicCockpit();},1000);}
async function beginRaceNow(){const ev=currentEvent(state.race),s=ensureSession(ev),rule=eventRule(state.race,ev);try{if(lapwiz.connected)await lapwiz.start(rule);}catch(e){toast(`LapWiz START: ${e.message}`);return;}s.phase='running';s.startedAtPerf=performance.now();s.startedAtEpoch=Date.now();s.finishedAtEpoch=null;s.timeExpired=false;Object.values(s.live).forEach(v=>Object.assign(v,blankLive()));logEvent(`Старт: ${ev.label}`);startTicker();render();}
async function finishSession(reason='Финиш судьёй'){const s=state.session;if(!s)return;if(lapwiz.connected&&lapwiz.running){try{await lapwiz.stop();}catch(e){toast(`STOP: ${e.message}`);}}s.phase='finished';s.finishedAtEpoch=Date.now();logEvent(reason);state.resultsOpen=true;render();}
async function stopSession(){if(state.countdownTick){clearInterval(state.countdownTick);state.countdownTick=null;}await finishSession('Аварийный STOP');}
function checkSessionLimit(){const ev=currentEvent(state.race),s=state.session;if(!ev||!s||s.phase!=='running')return;const r=eventRule(state.race,ev),elapsed=sessionElapsed(s);if(r.limitType==='time'&&elapsed>=r.durationMin*60000&&!s.timeExpired){s.timeExpired=true;s.phase='finishing';Object.values(s.live).forEach(v=>{if(!v.finished)v.needsFinish=true;});toast('Время истекло — финиш на следующем проходе');}if(r.limitType==='laps'){const all=Object.values(s.live).every(v=>v.finished);if(all)finishSession('Все пилоты финишировали');}}
function processPass(transponder,deviceMs=null,source='MANUAL'){const ev=currentEvent(state.race),s=state.session;if(!ev||!s||!['running','finishing'].includes(s.phase))return;const p=getEventPilots(state.race,ev).find(x=>String(x.transponder)===String(transponder));if(!p){s.unknown[transponder]=(s.unknown[transponder]||0)+1;if(source==='LAPWIZ')lapwiz.unknownBeep();toast(`Неизвестный ID ${transponder}`);return;}if(source==='LAPWIZ'&&state.settings.lapSound)lapwiz.beep(true);processPilotPass(p,deviceMs,source);}
function processPilotPass(p,deviceMs=null,source='MANUAL'){const ev=currentEvent(state.race),s=state.session;if(!ev||!s||!['running','finishing'].includes(s.phase))return;const l=s.live[p.id]||blankLive();if(l.finished)return;const now=performance.now();let lapMs=null;if(Number.isFinite(deviceMs)){if(Number.isFinite(l.lastDeviceMs)&&deviceMs>l.lastDeviceMs)lapMs=deviceMs-l.lastDeviceMs;else if(!l.lastDeviceMs&&deviceMs>0)lapMs=deviceMs;l.lastDeviceMs=deviceMs;}if(!Number.isFinite(lapMs)||lapMs<=0)lapMs=now-(l.lastPassPerf??s.startedAtPerf);l.lastPassPerf=now;l.lastLapMs=lapMs;l.bestLapMs=Math.min(l.bestLapMs,lapMs);l.laps++;l.elapsedMs=Number.isFinite(deviceMs)&&deviceMs>0?deviceMs:now-s.startedAtPerf;const rule=eventRule(state.race,ev);if(rule.limitType==='laps'&&l.laps>=rule.targetLaps){l.finished=true;l.finishedAt=l.elapsedMs;}if(s.phase==='finishing'&&s.timeExpired){l.finished=true;l.finishedAt=l.elapsedMs;}s.live[p.id]=l;s.lastPass=`${p.name} · ${l.laps} · ${fmtMs(lapMs)}`;if(source==='MANUAL'&&state.settings.lapSound)lapwiz.beep(true);updateDynamicCockpit();if(Object.values(s.live).every(v=>v.finished)&&(rule.limitType==='laps'||s.phase==='finishing'))finishSession('Все пилоты завершили заезд');}
function logEvent(text){state.race.runtime.eventLog.push({time:new Date().toISOString(),text});persistRace();}
function makeDraftResult(pilots,session){return pilots.map((p,i)=>{const l=session?.live?.[p.id]||blankLive();return{pilotId:p.id,name:p.name,status:'FIN',place:i+1,laps:l.laps,elapsedMs:l.elapsedMs};});}
function readEditedResult(){const ev=currentEvent(state.race),ranked=liveRanking(getEventPilots(state.race,ev),state.session);return ranked.map((p,i)=>{const st=document.querySelector(`[data-result-status="${CSS.escape(String(p.id))}"]`)?.value||'FIN',place=Number(document.querySelector(`[data-result-place="${CSS.escape(String(p.id))}"]`)?.value||i+1);return{pilotId:p.id,status:st,place:st==='FIN'?place:null,dnfOrder:st==='DNF'?i+1:null};});}
function saveCurrentEventResult(){const race=state.race,ev=currentEvent(race),s=state.session;if(!ev||s?.phase!=='finished')return toast('Сначала завершите заезд');try{const result=readEditedResult();if(ev.type==='qualifying')saveQualifyingEvent(race,ev.key,result);else saveFinalEvent(race,ev.key,result);syncChampionshipIfFinished(race);persistRace();state.session=null;state.resultsOpen=false;toast('Результат сохранён. Следующий заезд подготовлен.');render();}catch(e){toast(e.message);}}

function championshipsView(){return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">СЕЗОНЫ</div><h1>Чемпионаты</h1><p>Отдельный общий раздел Legion RX. Этапы получают итоговые очки из завершённых RallyCross-соревнований.</p></div><button class="btn primary" data-action="new-champ">＋ Чемпионат</button></div><div class="grid grid2">${state.championships.length?state.championships.map(c=>champCard(c)).join(''):`<div class="card empty">Пока нет чемпионатов.</div>`}</div></section>`;}
function champCard(c){const standings=champStandings(c);return `<article class="card"><div class="sectionLabel">${esc(c.season)}</div><h2>${esc(c.name)}</h2><p>${c.stages.length} этапов · план ${c.stagesPlanned}</p>${standings.length?`<div class="tableWrap"><table class="table"><thead><tr><th>Место</th><th>Пилот</th><th>Очки</th></tr></thead><tbody>${standings.slice(0,10).map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td><b>${r.total}</b></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Нет завершённых этапов.</div>`}</article>`;}
function champStandings(c){const m=new Map();(c.stages||[]).forEach(s=>(s.results||[]).forEach(r=>{const row=m.get(r.driverId)||{driverId:r.driverId,name:r.name,total:0};row.total+=Number(r.points||0);m.set(r.driverId,row);}));return[...m.values()].sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name));}
function syncChampionshipIfFinished(race){if(race.stage!=='finished'||!race.championshipId)return;const c=state.championships.find(x=>x.id===race.championshipId);if(!c)return;const stageNo=Number(race.championshipStageNumber)||((c.stages?.length||0)+1),results=race.finalProtocol.map(r=>{const p=getPilot(race,r.pilotId);return{driverId:p.profileId||p.id,name:p.name,place:r.place,points:r.eventPoints,status:r.status};});const stage={number:stageNo,raceId:race.id,name:race.eventName,date:race.eventDate,results};const idx=c.stages.findIndex(s=>s.raceId===race.id||s.number===stageNo);if(idx>=0)c.stages[idx]=stage;else c.stages.push(stage);save(KEYS.champ,state.championships);}

function pilotsView(){return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">ОБЩАЯ БАЗА</div><h1>Пилоты</h1><p>Профиль используется в соревнованиях; транспондер хранится здесь и переносится в состав гонки.</p></div><button class="btn primary" data-action="new-db-pilot">＋ Пилот</button></div><div class="card"><div class="list">${state.pilotDb.length?state.pilotDb.map(p=>`<div class="listRow"><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${esc(p.name)}</div><div class="sub">${esc(p.club||'Без клуба')} · ID транспондера ${esc(p.transponder||'—')}</div></div><button class="btn secondary" data-edit-pilot="${p.id}">Изменить</button><button class="btn danger" data-delete-pilot="${p.id}">Удалить</button></div>`).join(''):`<div class="empty">Создайте первый профиль пилота.</div>`}</div></div></section>`;}

function settingsView(){return `<section class="page"><div class="pageHeader"><div><div class="sectionLabel">СИСТЕМА</div><h1>Настройки</h1><p>Оболочка меняется отдельно от спортивной логики.</p></div></div><div class="settingsGrid">
 <article class="card settingGroup"><h3>${uiIcon('settings','widgetIcon')} Интерфейс</h3><div class="toggleRow"><span>Тёмная тема</span><input class="toggle" id="darkToggle" type="checkbox" ${state.settings.theme==='dark'?'checked':''}></div><div class="field" style="margin-top:12px"><label>Язык интерфейса</label><select id="langSelect"><option value="ru" ${state.settings.lang==='ru'?'selected':''}>Русский</option><option value="en" ${state.settings.lang==='en'?'selected':''}>English</option></select></div><p>English mode translates the main shell, controls and settings. Sport-specific result abbreviations FIN/DNF/DNS/DSQ remain universal.</p></article>

 <article class="card settingGroup designLabCard"><h3>${uiIcon('settings','widgetIcon')} Design Lab</h3><p>Живая настройка геометрии интерфейса без правки CSS: радиусы, отступы, высота кнопок, ширина контента и сетка карточек.</p><div class="designLabSample"><span></span><span></span><span></span></div><button class="btn primary" data-action="open-design-lab">Открыть Design Lab</button></article>
 <article class="card settingGroup"><h3>${uiIcon('bluetooth','widgetIcon')} LapWiz</h3><div class="toggleRow"><span>Звук прохода</span><input class="toggle" id="soundToggle" type="checkbox" ${state.settings.lapSound?'checked':''}></div><div class="field" style="margin-top:12px"><label>Минимальное время круга, сек</label><input id="settingsMinLap" type="number" min="1" max="60" value="${state.settings.minLapSec}"></div><div class="btnRow" style="margin-top:12px">${lapwiz.connected?`<button class="btn secondary" data-action="lap-disconnect">Отключить LapWiz</button>`:`<button class="btn primary" data-action="lap-connect">Подключить LapWiz</button>`}</div><p>BLE: FFF0 / команды FFF3 / уведомления FFF4. Android Chrome + HTTPS.</p></article>
 <article class="card settingGroup"><h3>${uiIcon('flag','widgetIcon')} Значения по умолчанию</h3><div class="formGrid"><div class="field"><label>Квалификация, мин</label><input id="settingsQMin" type="number" value="${state.settings.qualificationMinutes}"></div><div class="field"><label>Финал, кругов</label><input id="settingsFLaps" type="number" value="${state.settings.finalLaps}"></div><div class="field"><label>Отсчёт, сек</label><input id="settingsCountdown" type="number" value="${state.settings.countdownSec}"></div></div><button class="btn primary" style="margin-top:12px" data-action="save-settings">Сохранить</button></article>
 <article class="card settingGroup"><h3>О приложении</h3><p><b>Legion RX 4.0.4 Alpha</b></p><p>Новая мультисистемная оболочка. RallyCross-движок перенесён из Championship Edition v3.4. LapWiz Core основан на протестированном протоколе v0.5 Sound.</p><div class="list"><div class="listRow"><div class="grow"><b>Ралли-спринт</b><div class="sub">модуль ещё не реализован</div></div><span class="badge soon">СКОРО</span></div><div class="listRow"><div class="grow"><b>Classic RC</b><div class="sub">модуль ещё не реализован</div></div><span class="badge soon">СКОРО</span></div><div class="listRow"><div class="grow"><b>Автоматизация / диктор / Broadcast</b><div class="sub">архитектурно зарезервировано</div></div><span class="badge soon">СКОРО</span></div></div></article>
 </div></section>`;}

function bindView(){
 $$('[data-nav]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.nav)));
 $$('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset.action,b)));
 $$('[data-remove-race-pilot]').forEach(b=>b.addEventListener('click',()=>{if(state.race.stage!=='setup')return;state.race.pilots=state.race.pilots.filter(p=>p.id!==b.dataset.removeRacePilot);state.race.pilots.forEach((p,i)=>p.registrationOrder=i+1);persistRace();render();}));
 $$('[data-edit-pilot]').forEach(b=>b.addEventListener('click',()=>pilotModal(state.pilotDb.find(p=>p.id===b.dataset.editPilot))));
 $$('[data-delete-pilot]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Удалить профиль из базы?')){state.pilotDb=state.pilotDb.filter(p=>p.id!==b.dataset.deletePilot);save(KEYS.pilots,state.pilotDb);render();}}));
 $$('[data-show-event]').forEach(b=>b.addEventListener('click',()=>raceResultsModal(b.dataset.showEvent)));
 bindManualPasses();
}
function bindManualPasses(){$$('[data-manual-pass]').forEach(b=>b.onclick=()=>{const p=getPilot(state.race,b.dataset.manualPass);if(p)processPilotPass(p,null,'MANUAL');});}
async function handleAction(action){
 if(action==='home')return nav('home');if(action==='open-rx'||action==='open-current')return nav(state.race?.stage&&state.race.stage!=='setup'?'cockpit':'rallySetup');if(action==='cockpit')return nav('cockpit');
 if(action==='create-race'){const input={eventName:$('#raceName').value.trim()||'Legion RX Cup',eventDate:$('#raceDate').value,eventLocation:$('#raceLocation').value.trim(),championshipId:$('#raceChamp').value,qualificationMinutes:state.settings.qualificationMinutes,finalLaps:state.settings.finalLaps,minLapSec:state.settings.minLapSec,countdownSec:state.settings.countdownSec};state.race=makeRace(input);if(input.championshipId){const c=state.championships.find(x=>x.id===input.championshipId);state.race.championshipStageNumber=(c?.stages?.reduce((m,s)=>Math.max(m,s.number||0),0)||0)+1;}persistRace();return render();}
 if(action==='quick-pilot')return pilotModal(null,true);if(action==='add-db-pilot')return pilotPicker();
 if(action==='prepare-race'){if(state.race.pilots.length<2)return toast('Нужно минимум два пилота');state.race.eventName=$('#raceName').value.trim()||state.race.eventName;state.race.eventDate=$('#raceDate').value;state.race.eventLocation=$('#raceLocation').value.trim();state.race.championshipId=$('#raceChamp').value;state.race.qualifyingCount=Number($('#qCount').value);state.race.raceSettings={qualificationMinutes:Number($('#qMinutes').value)||5,finalLaps:Number($('#finalLaps').value)||7,minLapSec:Number($('#minLap').value)||2,countdownSec:state.settings.countdownSec};prepareRace(state.race);persistRace();state.session=null;return nav('cockpit');}
 if(action==='delete-race'){if(confirm('Удалить текущее соревнование?')){state.race=null;save(KEYS.race,null);nav('home');}return;}
 if(action==='toggle-events'){state.mobileEvents=true;return render();}if(action==='close-events'){state.mobileEvents=false;return render();}if(action==='toggle-widgets'){state.mobileWidgets=true;return render();}if(action==='close-widgets'){state.mobileWidgets=false;return render();}
 if(action==='race-results')return raceResultsModal();
 if(action==='tie-draw'){resolveQualificationTie(state.race);persistRace();state.session=null;toast('Жеребьёвка проведена. Финалы сформированы.');return render();}
 if(action==='toggle-results'){state.resultsOpen=!state.resultsOpen;return render();}if(action==='start-session')return beginCountdown();if(action==='finish-session')return finishSession();if(action==='stop-session')return stopSession();if(action==='save-event-result')return saveCurrentEventResult();
 if(action==='lap-connect'){try{lapwiz.ensureAudio();await lapwiz.connect();toast('LapWiz подключён');updateHeader();render();}catch(e){toast(e.message);}return;}if(action==='lap-disconnect'){await lapwiz.disconnect();toast('LapWiz отключён');updateHeader();render();return;}
 if(action==='new-db-pilot')return pilotModal();if(action==='new-champ')return championshipModal();if(action==='open-design-lab')return openDesignLab();
 if(action==='save-settings'){state.settings.theme=$('#darkToggle')?.checked?'dark':'light';state.settings.lang=$('#langSelect')?.value||'ru';state.settings.lapSound=Boolean($('#soundToggle')?.checked);state.settings.minLapSec=Number($('#settingsMinLap')?.value)||2;state.settings.qualificationMinutes=Number($('#settingsQMin')?.value)||5;state.settings.finalLaps=Number($('#settingsFLaps')?.value)||7;state.settings.countdownSec=Number($('#settingsCountdown')?.value)||5;save(KEYS.settings,state.settings);applySettings();toast('Настройки сохранены');return render();}
 if(action==='archive-race'){archiveCurrentRace();return;}
}


function openDesignLab(){
 const ui={...state.settings.ui};
 const controls=[
  ['cardRadius','Карточки','px',0,32],['tileRadius','Карточки дисциплин','px',0,32],['buttonRadius','Кнопки','px',0,28],['inputRadius','Поля','px',0,24],
  ['iconRadius','Иконки / плашки','px',0,24],['heroRadius','Главный баннер','px',0,36],['widgetRadius','Виджеты пульта','px',0,28],['modalRadius','Окна','px',0,30],
  ['cardPadding','Внутренний отступ карточек','px',10,32],['sectionGap','Расстояние между блоками','px',6,28],['buttonHeight','Высота кнопок пульта','px',40,70],['contentWidth','Ширина контента на ПК','px',900,1600]
 ];
 $('#modalHost').innerHTML=`<div class="designBackdrop" id="designBackdrop"><aside class="designDrawer"><div class="designHead"><div><div class="sectionLabel">LIVE UI EDITOR</div><h2>Design Lab</h2><p>Крути значения — Legion RX меняется сразу.</p></div><button class="iconBtn" id="closeDesignLab">×</button></div>
 <div class="designScroll"><section class="designSection"><h3>Радиусы и размеры</h3>${controls.map(([key,label,unit,min,max])=>`<label class="rangeRow"><span><b>${label}</b><output id="out_${key}">${ui[key]}${unit}</output></span><input type="range" min="${min}" max="${max}" step="1" value="${ui[key]}" data-ui-token="${key}"></label>`).join('')}</section>
 <section class="designSection"><h3>Главная страница</h3><label class="field"><span>Карточек дисциплин в ряд</span><select id="designCols"><option value="3" ${ui.disciplineCols===3?'selected':''}>3 — широко</option><option value="2" ${ui.disciplineCols===2?'selected':''}>2 — крупнее</option><option value="1" ${ui.disciplineCols===1?'selected':''}>1 — вертикально</option></select></label></section>
 <section class="designSection"><h3>Быстрые пресеты радиуса</h3><div class="presetRow"><button class="btn secondary" data-radius-preset="square">Строже</button><button class="btn secondary" data-radius-preset="medium">Средне</button><button class="btn secondary" data-radius-preset="soft">Мягко</button></div></section>
 </div><div class="designFooter"><button class="btn secondary" id="resetDesignLab">Сбросить</button><button class="btn secondary" id="copyDesignJson">Показать JSON</button><button class="btn primary" id="saveDesignLab">Сохранить</button></div></aside></div>`;
 const sync=()=>{applyUiTokens(ui);document.querySelectorAll('[data-ui-token]').forEach(inp=>{const out=$(`#out_${inp.dataset.uiToken}`);if(out)out.textContent=`${ui[inp.dataset.uiToken]}px`;});};
 $$('[data-ui-token]').forEach(inp=>inp.addEventListener('input',()=>{ui[inp.dataset.uiToken]=Number(inp.value);sync();}));
 $('#designCols').addEventListener('change',e=>{ui.disciplineCols=Number(e.target.value);sync();});
 $$('[data-radius-preset]').forEach(b=>b.addEventListener('click',()=>{const p=b.dataset.radiusPreset,vals=p==='square'?{cardRadius:6,tileRadius:8,buttonRadius:6,inputRadius:6,iconRadius:8,heroRadius:10,widgetRadius:8,modalRadius:10}:p==='medium'?{cardRadius:14,tileRadius:14,buttonRadius:9,inputRadius:8,iconRadius:10,heroRadius:18,widgetRadius:12,modalRadius:14}:{cardRadius:22,tileRadius:24,buttonRadius:14,inputRadius:12,iconRadius:14,heroRadius:28,widgetRadius:18,modalRadius:22};Object.assign(ui,vals);$$('[data-ui-token]').forEach(inp=>{if(vals[inp.dataset.uiToken]!=null)inp.value=vals[inp.dataset.uiToken];});sync();}));
 $('#closeDesignLab').onclick=()=>{applyUiTokens(state.settings.ui);closeModal();};
 $('#resetDesignLab').onclick=()=>{Object.assign(ui,defaultUi);$$('[data-ui-token]').forEach(inp=>inp.value=ui[inp.dataset.uiToken]);$('#designCols').value=String(ui.disciplineCols);sync();};
 $('#saveDesignLab').onclick=()=>{state.settings.ui={...ui};save(KEYS.settings,state.settings);applyUiTokens();closeModal();toast('Дизайн сохранён');};
 $('#copyDesignJson').onclick=()=>{const text=JSON.stringify(ui,null,2);const w=window.open('','_blank','width=520,height=680');if(w){w.document.write(`<pre style="font:14px/1.5 monospace;white-space:pre-wrap;padding:20px">${esc(text)}</pre>`);w.document.close();}else toast('Разрешите всплывающее окно для JSON');};
 sync();
}


function raceResultsModal(focusKey=''){
 const race=state.race;if(!race)return;
 updateStandings(race);
 const completed=eventList(race).filter(e=>e.saved);
 const eventTables=completed.map(e=>{
   const rows=(e.result||[]).map((r,i)=>{const p=getPilot(race,r.pilotId);return `<tr><td>${r.status==='FIN'?(r.place||i+1):esc(r.status)}</td><td>${esc(p?.name||'—')}</td><td>${r.status==='DNF'&&r.dnfOrder?`DNF-${r.dnfOrder}`:'—'}</td></tr>`;}).join('');
   return `<details ${focusKey===e.key?'open':''} class="card" style="box-shadow:none;margin-bottom:8px"><summary style="cursor:pointer;font-weight:850">${esc(e.label)}</summary><div class="tableWrap" style="margin-top:10px"><table class="table"><thead><tr><th>Место</th><th>Пилот</th><th>Статус</th></tr></thead><tbody>${rows}</tbody></table></div></details>`;
 }).join('');
 const qrows=race.pilots.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td>${Array.from({length:race.qualifyingCount},(_,k)=>{const q=p.qualifying.find(x=>x.round===k+1);return `<td>${q?q.status==='FIN'?`${q.place} (${q.points})`:esc(q.status):'—'}</td>`}).join('')}<td><b>${p.best3}</b></td></tr>`).join('');
 const main=race.finals?.length?buildMainStandings(race):[];
 const mainRows=main.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(getPilot(race,r.pilotId)?.name||'—')}</td>${r.scores.map(v=>`<td>${v??'—'}</td>`).join('')}<td><b>${r.total??'—'}</b></td></tr>`).join('');
 $('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal" style="width:min(980px,100%)"><div class="modalHead"><div><div class="sectionLabel">РЕЗУЛЬТАТЫ</div><h2>${esc(race.eventName)}</h2></div><button class="iconBtn" id="closeModal">×</button></div>
 <h3>Квалификационный рейтинг</h3><div class="tableWrap"><table class="table"><thead><tr><th>POS</th><th>Пилот</th>${Array.from({length:race.qualifyingCount},(_,i)=>`<th>Q${i+1}</th>`).join('')}<th>Best 3</th></tr></thead><tbody>${qrows}</tbody></table></div>
 ${main.length?`<h3 style="margin-top:16px">Финал A</h3><div class="tableWrap"><table class="table"><thead><tr><th>POS</th><th>Пилот</th><th>A1</th><th>A2</th><th>A3</th><th>Лучшие 2</th></tr></thead><tbody>${mainRows}</tbody></table></div>`:''}
 <h3 style="margin-top:16px">Завершённые заезды</h3>${eventTables||'<div class="empty">Пока нет завершённых заездов.</div>'}
 ${race.finalProtocol?.length?`<h3 style="margin-top:16px">Итоговый протокол</h3><div class="tableWrap"><table class="table"><thead><tr><th>Место</th><th>Пилот</th><th>Очки этапа</th><th>Источник</th></tr></thead><tbody>${race.finalProtocol.map(r=>`<tr><td>${r.place}</td><td>${esc(getPilot(race,r.pilotId)?.name||'—')}</td><td>${r.eventPoints}</td><td>${esc(r.source)}</td></tr>`).join('')}</tbody></table></div>`:''}
 </div></div>`;$('#closeModal').onclick=closeModal;
}

function pilotModal(existing=null,addToRace=false){const id=existing?.id||uid('profile');$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">ПИЛОТ</div><h2>${existing?'Редактировать':'Новый профиль'}</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="formGrid"><div class="field"><label>Фамилия Имя</label><input id="mName" value="${esc(existing?.name||'')}"></div><div class="field"><label>Клуб</label><input id="mClub" value="${esc(existing?.club||'')}"></div><div class="field"><label>Город</label><input id="mCity" value="${esc(existing?.city||'')}"></div><div class="field"><label>ID транспондера</label><input id="mTrans" inputmode="numeric" value="${esc(existing?.transponder||'')}"></div></div><div class="btnRow" style="margin-top:14px"><button class="btn primary" id="savePilotModal">Сохранить</button></div></div></div>`;$('#closeModal').onclick=closeModal;$('#savePilotModal').onclick=()=>{const name=$('#mName').value.trim();if(!name)return toast('Введите имя');const profile={id,name,club:$('#mClub').value.trim(),city:$('#mCity').value.trim(),transponder:$('#mTrans').value.trim(),photo:existing?.photo||''};const idx=state.pilotDb.findIndex(p=>p.id===id);if(idx>=0)state.pilotDb[idx]=profile;else state.pilotDb.push(profile);save(KEYS.pilots,state.pilotDb);if(addToRace&&state.race?.stage==='setup'&&!state.race.pilots.some(p=>p.profileId===id)){const p=makePilot({...profile,profileId:id},state.race.pilots.length+1);p.profileId=id;state.race.pilots.push(p);persistRace();}closeModal();render();};}
function pilotPicker(){const available=state.pilotDb.filter(p=>!state.race.pilots.some(r=>r.profileId===p.id));$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><div><div class="sectionLabel">БАЗА</div><h2>Добавить пилотов</h2></div><button class="iconBtn" id="closeModal">×</button></div><div class="list">${available.length?available.map(p=>`<label class="listRow"><input type="checkbox" data-pick-pilot="${p.id}"><div class="avatar">${nameInitials(p.name)}</div><div class="grow"><div class="name">${esc(p.name)}</div><div class="sub">ID ${esc(p.transponder||'—')}</div></div></label>`).join(''):`<div class="empty">Все пилоты из базы уже добавлены.</div>`}</div><button class="btn primary" id="addPicked" style="margin-top:12px">Добавить выбранных</button></div></div>`;$('#closeModal').onclick=closeModal;$('#addPicked').onclick=()=>{$$('[data-pick-pilot]:checked').forEach(ch=>{const profile=state.pilotDb.find(p=>p.id===ch.dataset.pickPilot);if(profile){const p=makePilot({...profile,profileId:profile.id},state.race.pilots.length+1);p.profileId=profile.id;state.race.pilots.push(p);}});persistRace();closeModal();render();};}
function championshipModal(){$('#modalHost').innerHTML=`<div class="modalBackdrop"><div class="modal"><div class="modalHead"><h2>Новый чемпионат</h2><button class="iconBtn" id="closeModal">×</button></div><div class="formGrid"><div class="field"><label>Название</label><input id="cName" value="Legion RX Cup"></div><div class="field"><label>Сезон</label><input id="cSeason" type="number" value="${new Date().getFullYear()}"></div><div class="field"><label>План этапов</label><input id="cStages" type="number" value="6"></div></div><button class="btn primary" id="saveChamp" style="margin-top:12px">Создать</button></div></div>`;$('#closeModal').onclick=closeModal;$('#saveChamp').onclick=()=>{state.championships.push({id:uid('champ'),name:$('#cName').value.trim()||'Legion RX Cup',season:Number($('#cSeason').value),stagesPlanned:Number($('#cStages').value)||6,stages:[]});save(KEYS.champ,state.championships);closeModal();render();};}
function closeModal(){$('#modalHost').innerHTML='';}
function archiveCurrentRace(){if(!state.race)return;const idx=state.archive.findIndex(r=>r.id===state.race.id);if(idx>=0)state.archive[idx]=JSON.parse(JSON.stringify(state.race));else state.archive.push(JSON.parse(JSON.stringify(state.race)));save(KEYS.archive,state.archive);toast('Соревнование сохранено в архив');}

lapwiz.addEventListener('pass',e=>processPass(e.detail.transponder,e.detail.deviceMs,'LAPWIZ'));lapwiz.addEventListener('status',()=>updateHeader());
window.addEventListener('pointerdown',()=>lapwiz.ensureAudio(),{once:true});
window.addEventListener('beforeunload',()=>persistAll());

$('#designQuickBtn')?.addEventListener('click',openDesignLab);
applySettings();render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
